contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.withdraw(); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == 0);
    }

    receive() external payable {}
}

